_ngcontent-%COMP%]   .transacao-card[_ngcontent-%COMP%]   .card-tipo.despesa[_ngcontent-%COMP%] {\n  background-color: rgba(239, 68, 68, 0.2);\n  color: #fca5a5;\n}\n.transacao-card[_ngcontent-%COMP%]   .card-body[_ngcontent-%COMP%] {\n  margin-bottom: 1rem;\n}\n.transacao-card[_ngcontent-%COMP%]   .card-descricao[_ngcontent-%COMP%] {\n  font-weight: 600;\n  margin-bottom: 0.5rem;\n  color: var(--text-light);\n}\nbody.dark-mode[_ngcontent-%COMP%]   .transacao-card[_ngcontent-%COMP%]   .card-descricao[_ngcontent-%COMP%] {\n  color: var(--text-dark);\n}\n.transacao-card[_ngcontent-%COMP%]   .card-categoria[_ngcontent-%COMP%] {\n  font-size: 0.85rem;\n  color: var(--text-light-muted);\n}\nbody.dark-mode[_ngcontent-%COMP%]   .transacao-card[_ngcontent-%COMP%]   .card-categoria[_ngcontent-%COMP%] {\n  color: var(--text-dark-muted);\n}\n.transacao-card[_ngcontent-%COMP%]   .card-footer[_ngcontent-%COMP%] {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 1rem;\n}\n.transacao-card[_ngcontent-%COMP%]   .card-valor[_ngcontent-%COMP%] {\n  font-size: 1.5rem;\n  font-weight: 700;\n}\n.transacao-card[_ngcontent-%COMP%]   .card-valor.receita[_ngcontent-%COMP%] {\n  color: var(--success-color);\n}\n.transacao-card[_ngcontent-%COMP%]   .card-valor.despesa[_ngcontent-%COMP%] {\n  color: var(--error-color);\n}\n.transacao-card[_ngcontent-%COMP%]   .card-acoes[_ngcontent-%COMP%] {\n  display: flex;\n  gap: 0.5rem;\n}\n.transacao-card[_ngcontent-%COMP%]   .card-acoes[_ngcontent-%COMP%]   .btn[_ngcontent-%COMP%] {\n  padding: 0.5rem;\n  min-width: 40px;\n  height: 40px;\n}\n\n.btn[_ngcontent-%COMP%] {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 0.5rem;\n  padding: 0.75rem 1.5rem;\n  border: none;\n  border-radius: 6px;\n  font-size: 1rem;\n  font-weight: 600;\n  cursor: pointer;\n  transition: all 0.3s ease;\n  font-family: inherit;\n}\n.btn[_ngcontent-%COMP%]:disabled {\n  opacity: 0.5;\n  cursor: not-allowed